        ('common', N'{"a11y.skip":"Skip to main content","nav.main":"Main navigation","brand.name":"Speed Test","brand.sub":"Connection check","lang.label":"Language","theme.label":"Theme","theme.glass":"Glassmorphism","theme.clay":"Claymorphism","theme.skeu":"Skeuomorphism","theme.neu":"Neumorphism","install.btn":"Install app","install.ios.title":"Install on iPhone or iPad","install.ios.text":"Tap the Share button in Safari, then choose \"Add to Home Screen\".","install.close":"Close","ft.rights":"All rights reserved.","nav.pages":"Pages"}', N'{"a11y.skip":"मुख्य सामग्री पर जाएं","nav.main":"मुख्य नेविगेशन","brand.name":"स्पीड टेस्ट","brand.sub":"कनेक्शन जांच","lang.label":"भाषा","theme.label":"थीम","theme.glass":"ग्लासमॉर्फिज़्म","theme.clay":"क्लेमॉर्फिज़्म","theme.skeu":"स्कियोमॉर्फिज़्म","theme.neu":"न्यूमॉर्फिज़्म","install.btn":"ऐप इंस्टॉल करें","install.ios.title":"iPhone या iPad पर इंस्टॉल करें","install.ios.text":"Safari में शेयर बटन दबाएं, फिर \"होम स्क्रीन में जोड़ें\" चुनें।","install.close":"बंद करें","ft.rights":"सर्वाधिकार सुरक्षित।","nav.pages":"पेज"}', N'{"a11y.skip":"انتقل إلى المحتوى الرئيسي","nav.main":"التنقل الرئيسي","brand.name":"اختبار السرعة","brand.sub":"فحص الاتصال","lang.label":"اللغة","theme.label":"المظهر","theme.glass":"زجاجي (Glassmorphism)","theme.clay":"طيني (Claymorphism)","theme.skeu":"واقعي (Skeuomorphism)","theme.neu":"ناعم (Neumorphism)","install.btn":"تثبيت التطبيق","install.ios.title":"التثبيت على iPhone أو iPad","install.ios.text":"اضغط على زر المشاركة في Safari، ثم اختر \"إضافة إلى الشاشة الرئيسية\".","install.close":"إغلاق","ft.rights":"جميع الحقوق محفوظة.","nav.pages":"الصفحات"}'),
        ('speedtest', N'{"st.h1a":"Internet speed test: how fast is your","st.h1b":"connection?","st.lead":"Measures ping, download and upload against our own speed test server. It takes about 25 seconds.","st.start":"Start speed test","st.stop":"Stop test","st.again":"Run test again","st.ready":"Ready when you are.","st.ping_phase":"Measuring ping and jitter…","st.down_phase":"Testing download speed…","st.up_phase":"Testing upload speed…","st.complete":"Test complete at {time}.","st.stopped":"Test stopped.","st.nonet":"No internet access. Please try again later.","st.note":"For the most accurate result, pause downloads and video calls on this device and others on the same network. Wi-Fi results also depend on how close you are to the router.","unit.mbps":"Mbps","unit.ms":"ms","unit.mbps_down":"Mbps download","unit.mbps_up":"Mbps upload","res.download":"Download","res.upload":"Upload","res.ping":"Ping","res.jitter":"Jitter","res.label":"Speed test results","res.loaded":"Latency under load","loaded.good":"Excellent: your connection stays responsive while busy.","loaded.fair":"Fair: calls and games may stutter while something is downloading.","loaded.bad":"High (bufferbloat): the connection lags badly when busy. A router with smart queue management (SQM) can help.","clk.now":"Time now","clk.elapsed":"Test time","off.title":"No internet access","off.text":"We couldn''t reach the network. Please check your connection and try again later.","off.retry":"Try again","conn.lead":"What the internet can see about your connection right now. Details come from your browser and public lookup services, so treat the location as approximate.","conn.isp":"Internet provider","conn.ip":"IP address","conn.ipv4":"IPv4 address","conn.ipv6":"IPv6 address","conn.mac":"MAC address","conn.location":"Location","conn.testServer":"Test server","conn.networkType":"Network type","conn.detecting":"Detecting…","conn.unavailable":"Not available","conn.noipv6":"Not detected (no IPv6 on this connection)","conn.mac_na":"Not available: browsers do not allow websites to read a MAC address.","conn.net.unknown":"Not reported by this browser","conn.net.wifi":"Wi-Fi","conn.net.cellular":"Mobile data","conn.net.ethernet":"Ethernet (cable)","conn.net.bluetooth":"Bluetooth","conn.net.other":"Other","conn.refresh":"Refresh details","conn.note":"Looked up in your browser from our server, ipify and ipwho.is. Nothing is stored on our servers.","svc.lead":"Live status of popular apps and mobile networks. Where a service publishes a status page we use it; for the rest we check that the site can be reached from your connection.","svc.group.apps":"Apps and websites","svc.group.telecom":"Mobile and broadband networks","svc.operational":"Operational","svc.degraded":"Degraded","svc.outage":"Outage","svc.unreachable":"Can''t reach","svc.checking":"Checking…","svc.all_ok":"Everything we checked is working.","svc.issues":"{n} service(s) have a problem.","svc.checked":"Last checked at {time}.","svc.refresh":"Check again","svc.official":"Official status page","svc.probe":"Reachability check","svc.open":"Open {name}","svc.note":"\"Reachability check\" means this browser could or could not open the site. It is not an official status, and ad blockers or a network block can also cause \"Can''t reach\".","act.share":"Share result","act.save":"Save result","act.saved":"Saved","act.image":"Download image","act.copy":"Copy text","act.copied":"Copied","share.title":"My internet speed","share.text":"My internet speed: {down} download, {up} upload, {ping} ms ping. Test yours free:","share.whatsapp":"WhatsApp","share.facebook":"Facebook","share.x":"X","share.telegram":"Telegram","share.menu":"Share on","hist.title":"Saved results","hist.empty":"No saved results yet. Run a test and press \"Save result\".","hist.note":"Results are stored only in this browser. Nothing is sent to a server.","hist.clear":"Clear all","hist.delete":"Delete","hist.item":"{down} down, {up} up, {ping} ms ping, {jitter} ms jitter","info.h2.intro":"Free internet speed test: check your download, upload and ping","info.intro":"This free internet speed test shows how fast your connection really is in about 25 seconds. Press Start speed test and it measures your download speed, upload speed, ping and jitter against our own speed test server. It works on any phone, tablet or computer, on Wi-Fi, mobile data or a cable, and you never need to sign up.","info.h2.mean":"What the results mean","info.mean.1":"Download speed (Mbps): how quickly data reaches you. It controls video streaming, web pages, app updates and file downloads.","info.mean.2":"Upload speed (Mbps): how quickly you send data. It matters for video calls, cloud backups, sharing large files and live streaming.","info.mean.3":"Ping (ms): the delay between your device and a server. Lower is better, and under 20 ms is excellent for gaming and calls.","info.mean.4":"Jitter (ms): how much the ping changes. Lower is better, and steady jitter means smooth calls and games.","info.h2.good":"What is a good internet speed?","info.good":"As a rough guide, 5 to 10 Mbps handles one HD video stream, 25 Mbps suits a small household, and 100 Mbps or more is comfortable for several people streaming, working from home and gaming at once. Video calls need a steady upload speed of a few Mbps, so a fast download alone does not guarantee a good call.","info.h2.accurate":"How to get the most accurate speed test result","info.acc.1":"Pause downloads, streaming and video calls on every device on your network.","info.acc.2":"Move close to your router, or connect a device with a cable.","info.acc.3":"Close other browser tabs and turn off any VPN.","info.acc.4":"Run the test two or three times and compare the results.","info.h2.fix":"How to fix slow internet","info.fix.1":"Restart your router and modem, then wait two minutes.","info.fix.2":"Place the router in an open, central spot, away from walls and appliances.","info.fix.3":"Switch to the 5 GHz Wi-Fi band for higher speed at short range.","info.fix.4":"Disconnect devices you are not using, and pause large background updates.","info.fix.5":"Update the router firmware, and replace an old router if it is several years old.","info.fix.6":"If speeds stay far below your plan on a cable connection, contact your internet provider.","info.h2.faq":"Frequently asked questions","faq.1.q":"How accurate is this internet speed test?","faq.1.a":"It measures against our own speed test server, so it shows your real-world speed to that server over the public internet. Results can vary slightly between runs because your connection, Wi-Fi signal and other devices on your network change from moment to moment. Run it two or three times and compare.","faq.2.q":"What is a good internet speed?","faq.2.a":"For most homes, 25 to 100 Mbps download is enough for HD streaming, video calls and browsing. Households with many devices, 4K streaming or large downloads benefit from 100 to 500 Mbps. Upload matters for video calls, cloud backups and live streaming, so aim for at least 10 Mbps.","faq.3.q":"Why is my speed lower than what my provider advertises?","faq.3.a":"Providers advertise the best-case speed on a wired connection. Wi-Fi distance, walls, router age, busy evening hours, other devices and a congested network can all reduce what you actually get. Testing with a cable connected to your router shows the true speed of your plan.","faq.4.q":"What is the difference between download and upload speed?","faq.4.a":"Download speed is how fast data comes to your device, which affects streaming, browsing and downloading files. Upload speed is how fast data leaves your device, which affects video calls, sending large files and posting videos.","faq.5.q":"What is ping and what is a good ping?","faq.5.a":"Ping, also called latency, is the time in milliseconds for data to travel to a server and back. Under 20 ms is excellent, 20 to 50 ms is good for gaming and calls, and above 100 ms can feel laggy.","faq.6.q":"What is jitter?","faq.6.a":"Jitter is how much your ping changes from one moment to the next. Low jitter means a steady connection. High jitter causes choppy video calls, voice dropouts and online game lag even when your download speed is high.","faq.7.q":"Is this speed test free?","faq.7.a":"Yes. It is completely free, needs no signup and works on phones, tablets and computers in any modern browser.","faq.8.q":"Does the test use a lot of data?","faq.8.a":"A full test downloads and uploads test data for about 25 seconds, so it can use a noticeable amount of data on a fast connection. If you are on a limited mobile plan, run it on Wi-Fi or sparingly.","seo.home.title":"Internet Speed Test: Check Download, Upload and Ping (Free)","seo.home.desc":"Free internet speed test. Check your download speed, upload speed, ping and jitter in 25 seconds. Works on phone and PC, no signup. Learn what a good speed is.","unit.gbps":"Gbps","unit.gbps_down":"Gbps download","unit.gbps_up":"Gbps upload"}', N'{"st.h1a":"इंटरनेट स्पीड टेस्ट: आपका","st.h1b":"कनेक्शन कितना तेज़ है?","st.lead":"यह हमारे अपने स्पीड टेस्ट सर्वर के साथ पिंग, डाउनलोड और अपलोड स्पीड नापता है। इसमें लगभग 25 सेकंड लगते हैं।","st.start":"स्पीड टेस्ट शुरू करें","st.stop":"टेस्ट रोकें","st.again":"टेस्ट फिर चलाएं","st.ready":"आप जब चाहें शुरू करें।","st.ping_phase":"पिंग और जिटर नापा जा रहा है…","st.down_phase":"डाउनलोड स्पीड जांची जा रही है…","st.up_phase":"अपलोड स्पीड जांची जा रही है…","st.complete":"टेस्ट {time} पर पूरा हुआ।","st.stopped":"टेस्ट रोक दिया गया।","st.nonet":"इंटरनेट उपलब्ध नहीं है। कृपया बाद में फिर कोशिश करें।","st.note":"सबसे सही नतीजे के लिए इस डिवाइस और नेटवर्क के दूसरे डिवाइस पर डाउनलोड और वीडियो कॉल रोक दें। Wi-Fi के नतीजे इस पर भी निर्भर करते हैं कि आप राउटर के कितने पास हैं।","unit.mbps":"Mbps","unit.ms":"ms","unit.mbps_down":"Mbps डाउनलोड","unit.mbps_up":"Mbps अपलोड","res.download":"डाउनलोड","res.upload":"अपलोड","res.ping":"पिंग","res.jitter":"जिटर","res.label":"स्पीड टेस्ट के नतीजे","res.loaded":"लोड के दौरान लेटेंसी","loaded.good":"बहुत अच्छा: व्यस्त होने पर भी कनेक्शन तेज़ बना रहता है।","loaded.fair":"ठीक-ठाक: कुछ डाउनलोड होते समय कॉल और गेम अटक सकते हैं।","loaded.bad":"ज़्यादा (बफरब्लोट): व्यस्त होने पर कनेक्शन बहुत लैग करता है। स्मार्ट क्यू मैनेजमेंट (SQM) वाला राउटर मदद कर सकता है।","clk.now":"अभी का समय","clk.elapsed":"टेस्ट का समय","off.title":"इंटरनेट उपलब्ध नहीं है","off.text":"हम नेटवर्क तक नहीं पहुंच पाए। कृपया अपना कनेक्शन जांचें और बाद में फिर कोशिश करें।","off.retry":"फिर कोशिश करें","conn.lead":"इंटरनेट अभी आपके कनेक्शन के बारे में क्या देख सकता है। जानकारी आपके ब्राउज़र और सार्वजनिक लुकअप सेवाओं से आती है, इसलिए लोकेशन को अनुमानित मानें।","conn.isp":"इंटरनेट प्रदाता","conn.ip":"IP पता","conn.ipv4":"IPv4 पता","conn.ipv6":"IPv6 पता","conn.mac":"MAC पता","conn.location":"लोकेशन","conn.testServer":"टेस्ट सर्वर","conn.networkType":"नेटवर्क का प्रकार","conn.detecting":"पता लगाया जा रहा है…","conn.unavailable":"उपलब्ध नहीं","conn.noipv6":"नहीं मिला (इस कनेक्शन पर IPv6 नहीं है)","conn.mac_na":"उपलब्ध नहीं: ब्राउज़र वेबसाइटों को MAC पता पढ़ने नहीं देते।","conn.net.unknown":"इस ब्राउज़र ने नहीं बताया","conn.net.wifi":"वाई-फ़ाई","conn.net.cellular":"मोबाइल डेटा","conn.net.ethernet":"ईथरनेट (केबल)","conn.net.bluetooth":"ब्लूटूथ","conn.net.other":"अन्य","conn.refresh":"विवरण ताज़ा करें","conn.note":"आपके ब्राउज़र में हमारे सर्वर, ipify और ipwho.is से लिया गया। हमारे सर्वर पर कुछ भी सहेजा नहीं जाता।","svc.lead":"लोकप्रिय ऐप और मोबाइल नेटवर्क की लाइव स्थिति। जहां सेवा स्टेटस पेज देती है वही इस्तेमाल होता है; बाकी के लिए जांचते हैं कि आपके कनेक्शन से साइट खुलती है या नहीं।","svc.group.apps":"ऐप और वेबसाइट","svc.group.telecom":"मोबाइल और ब्रॉडबैंड नेटवर्क","svc.operational":"चालू","svc.degraded":"धीमी/आंशिक समस्या","svc.outage":"आउटेज","svc.unreachable":"पहुंच नहीं पा रहे","svc.checking":"जांच हो रही है…","svc.all_ok":"हमने जो जांचा वह सब ठीक चल रहा है।","svc.issues":"{n} सेवा(ओं) में समस्या है।","svc.checked":"आखिरी जांच {time} पर।","svc.refresh":"फिर जांचें","svc.official":"आधिकारिक स्टेटस पेज","svc.probe":"पहुंच की जांच","svc.open":"{name} खोलें","svc.note":"\"पहुंच की जांच\" का मतलब है कि यह ब्राउज़र साइट खोल पाया या नहीं। यह आधिकारिक स्थिति नहीं है, और ऐड ब्लॉकर या नेटवर्क ब्लॉक से भी \"पहुंच नहीं पा रहे\" दिख सकता है।","act.share":"नतीजा शेयर करें","act.save":"नतीजा सेव करें","act.saved":"सेव हो गया","act.image":"इमेज डाउनलोड करें","act.copy":"टेक्स्ट कॉपी करें","act.copied":"कॉपी हो गया","share.title":"मेरी इंटरनेट स्पीड","share.text":"मेरी इंटरनेट स्पीड: {down} डाउनलोड, {up} अपलोड, {ping} ms पिंग। अपनी स्पीड मुफ़्त में जांचें:","share.whatsapp":"WhatsApp","share.facebook":"Facebook","share.x":"X","share.telegram":"Telegram","share.menu":"यहां शेयर करें","hist.title":"सेव किए गए नतीजे","hist.empty":"अभी कोई नतीजा सेव नहीं है। टेस्ट चलाएं और \"नतीजा सेव करें\" दबाएं।","hist.note":"नतीजे सिर्फ़ इसी ब्राउज़र में रखे जाते हैं। कुछ भी सर्वर पर नहीं भेजा जाता।","hist.clear":"सब हटाएं","hist.delete":"हटाएं","hist.item":"{down} डाउनलोड, {up} अपलोड, {ping} ms पिंग, {jitter} ms जिटर","info.h2.intro":"मुफ़्त इंटरनेट स्पीड टेस्ट: डाउनलोड, अपलोड और पिंग जांचें","info.intro":"यह मुफ़्त इंटरनेट स्पीड टेस्ट लगभग 25 सेकंड में बता देता है कि आपका कनेक्शन असल में कितना तेज़ है। \"स्पीड टेस्ट शुरू करें\" दबाएं, और यह हमारे अपने स्पीड टेस्ट सर्वर के साथ आपकी डाउनलोड स्पीड, अपलोड स्पीड, पिंग और जिटर नापता है। यह किसी भी फ़ोन, टैबलेट या कंप्यूटर पर, Wi-Fi, मोबाइल डेटा या केबल पर चलता है, और साइन अप की ज़रूरत नहीं है।","info.h2.mean":"नतीजों का मतलब","info.mean.1":"डाउनलोड स्पीड (Mbps): डेटा आप तक कितनी तेज़ी से पहुंचता है। वीडियो स्ट्रीमिंग, वेब पेज, ऐप अपडेट और फ़ाइल डाउनलोड इसी पर निर्भर करते हैं।","info.mean.2":"अपलोड स्पीड (Mbps): आप कितनी तेज़ी से डेटा भेज पाते हैं। वीडियो कॉल, क्लाउड बैकअप, बड़ी फ़ाइलें भेजने और लाइव स्ट्रीमिंग के लिए यह ज़रूरी है।","info.mean.3":"पिंग (ms): आपके डिवाइस और सर्वर के बीच की देरी। कम होना बेहतर है, और 20 ms से कम गेमिंग और कॉल के लिए बहुत अच्छा है।","info.mean.4":"जिटर (ms): पिंग में कितना बदलाव आता है। कम होना बेहतर है, और स्थिर जिटर का मतलब है साफ़ कॉल और स्मूद गेम।","info.h2.good":"अच्छी इंटरनेट स्पीड कितनी होती है?","info.good":"मोटे तौर पर, 5 से 10 Mbps में एक HD वीडियो चलता है, 25 Mbps छोटे परिवार के लिए ठीक है, और 100 Mbps या ज़्यादा में कई लोग एक साथ स्ट्रीमिंग, घर से काम और गेमिंग आराम से कर सकते हैं। वीडियो कॉल के लिए कुछ Mbps की स्थिर अपलोड स्पीड चाहिए, इसलिए सिर्फ़ तेज़ डाउनलोड से अच्छी कॉल की गारंटी नहीं होती।","info.h2.accurate":"सबसे सही स्पीड टेस्ट नतीजा कैसे पाएं","info.acc.1":"अपने नेटवर्क के हर डिवाइस पर डाउनलोड, स्ट्रीमिंग और वीडियो कॉल रोक दें।","info.acc.2":"राउटर के पास जाएं, या किसी डिवाइस को केबल से जोड़ें।","info.acc.3":"ब्राउज़र के दूसरे टैब बंद करें और VPN बंद कर दें।","info.acc.4":"टेस्ट दो या तीन बार चलाएं और नतीजों की तुलना करें।","info.h2.fix":"धीमे इंटरनेट को कैसे ठीक करें","info.fix.1":"अपना राउटर और मॉडेम रीस्टार्ट करें, फिर दो मिनट रुकें।","info.fix.2":"राउटर को खुली, बीच की जगह पर रखें, दीवारों और बिजली के उपकरणों से दूर।","info.fix.3":"कम दूरी पर ज़्यादा स्पीड के लिए 5 GHz Wi-Fi बैंड पर जाएं।","info.fix.4":"जो डिवाइस इस्तेमाल में नहीं हैं उन्हें डिस्कनेक्ट करें, और बैकग्राउंड के बड़े अपडेट रोक दें।","info.fix.5":"राउटर का फ़र्मवेयर अपडेट करें, और अगर राउटर कई साल पुराना है तो बदल दें।","info.fix.6":"अगर केबल कनेक्शन पर भी स्पीड आपके प्लान से काफ़ी कम रहती है, तो अपने इंटरनेट प्रोवाइडर से संपर्क करें।","info.h2.faq":"अक्सर पूछे जाने वाले सवाल","faq.1.q":"यह इंटरनेट स्पीड टेस्ट कितना सही है?","faq.1.a":"यह हमारे अपने स्पीड टेस्ट सर्वर के साथ नापता है, इसलिए यह सार्वजनिक इंटरनेट पर उस सर्वर तक आपकी असली स्पीड दिखाता है। हर बार के नतीजों में थोड़ा फ़र्क़ हो सकता है, क्योंकि आपका कनेक्शन, Wi-Fi सिग्नल और नेटवर्क के दूसरे डिवाइस पल-पल बदलते रहते हैं। इसे दो या तीन बार चलाकर तुलना करें।","faq.2.q":"अच्छी इंटरनेट स्पीड कितनी होती है?","faq.2.a":"ज़्यादातर घरों के लिए 25 से 100 Mbps डाउनलोड HD स्ट्रीमिंग, वीडियो कॉल और ब्राउज़िंग के लिए काफ़ी है। जिन घरों में कई डिवाइस हैं, 4K स्ट्रीमिंग होती है या बड़े डाउनलोड होते हैं, उन्हें 100 से 500 Mbps से फ़ायदा होता है। वीडियो कॉल, क्लाउड बैकअप और लाइव स्ट्रीमिंग के लिए अपलोड भी मायने रखता है, इसलिए कम से कम 10 Mbps रखें।","faq.3.q":"मेरी स्पीड प्रोवाइडर के बताए से कम क्यों है?","faq.3.a":"प्रोवाइडर केबल कनेक्शन पर सबसे अच्छी स्थिति की स्पीड बताते हैं। Wi-Fi की दूरी, दीवारें, राउटर की उम्र, शाम की भीड़, दूसरे डिवाइस और भीड़ वाला नेटवर्क, सब असली स्पीड घटा सकते हैं। राउटर से केबल जोड़कर टेस्ट करने पर आपके प्लान की असली स्पीड दिखती है।","faq.4.q":"डाउनलोड और अपलोड स्पीड में क्या फ़र्क़ है?","faq.4.a":"डाउनलोड स्पीड बताती है कि डेटा आपके डिवाइस तक कितनी तेज़ी से आता है, जिसका असर स्ट्रीमिंग, ब्राउज़िंग और फ़ाइल डाउनलोड पर पड़ता है। अपलोड स्पीड बताती है कि डेटा आपके डिवाइस से कितनी तेज़ी से जाता है, जिसका असर वीडियो कॉल, बड़ी फ़ाइलें भेजने और वीडियो पोस्ट करने पर पड़ता है।","faq.5.q":"पिंग क्या है और अच्छी पिंग कितनी होती है?","faq.5.a":"पिंग, जिसे लेटेंसी भी कहते हैं, वह समय है (मिलीसेकंड में) जो डेटा को सर्वर तक जाने और वापस आने में लगता है। 20 ms से कम बहुत अच्छी है, 20 से 50 ms गेमिंग और कॉल के लिए अच्छी है, और 100 ms से ऊपर सुस्ती महसूस हो सकती है।","faq.6.q":"जिटर क्या है?","faq.6.a":"जिटर बताता है कि आपकी पिंग एक पल से दूसरे पल में कितनी बदलती है। कम जिटर का मतलब है स्थिर कनेक्शन। ज़्यादा जिटर से वीडियो कॉल अटकती है, आवाज़ कटती है और ऑनलाइन गेम में लैग आता है, भले ही डाउनलोड स्पीड ज़्यादा हो।","faq.7.q":"क्या यह स्पीड टेस्ट मुफ़्त है?","faq.7.a":"हां। यह पूरी तरह मुफ़्त है, साइन अप की ज़रूरत नहीं है, और किसी भी आधुनिक ब्राउज़र में फ़ोन, टैबलेट और कंप्यूटर पर चलता है।","faq.8.q":"क्या टेस्ट में बहुत डेटा खर्च होता है?","faq.8.a":"पूरा टेस्ट लगभग 25 सेकंड तक टेस्ट डेटा डाउनलोड और अपलोड करता है, इसलिए तेज़ कनेक्शन पर काफ़ी डेटा खर्च हो सकता है। अगर आपका मोबाइल प्लान सीमित है, तो इसे Wi-Fi पर या कम बार चलाएं।","seo.home.title":"इंटरनेट स्पीड टेस्ट: डाउनलोड, अपलोड और पिंग जांचें (मुफ़्त)","seo.home.desc":"मुफ़्त इंटरनेट स्पीड टेस्ट। 25 सेकंड में अपनी डाउनलोड स्पीड, अपलोड स्पीड, पिंग और जिटर जांचें। फ़ोन और पीसी पर चलता है, साइन अप नहीं चाहिए। जानें कि अच्छी स्पीड कितनी होती है।","unit.gbps":"Gbps","unit.gbps_down":"Gbps डाउनलोड","unit.gbps_up":"Gbps अपलोड"}', N'{"st.h1a":"اختبار سرعة الإنترنت: ما مدى سرعة","st.h1b":"اتصالك؟","st.lead":"يقيس زمن الاستجابة وسرعتي التنزيل والرفع مع خادم اختبار السرعة الخاص بنا. يستغرق نحو 25 ثانية.","st.start":"ابدأ اختبار السرعة","st.stop":"أوقف الاختبار","st.again":"أعد الاختبار","st.ready":"ابدأ متى شئت.","st.ping_phase":"جارٍ قياس زمن الاستجابة والاهتزاز…","st.down_phase":"جارٍ اختبار سرعة التنزيل…","st.up_phase":"جارٍ اختبار سرعة الرفع…","st.complete":"اكتمل الاختبار في {time}.","st.stopped":"تم إيقاف الاختبار.","st.nonet":"لا يوجد اتصال بالإنترنت. يرجى المحاولة لاحقًا.","st.note":"للحصول على أدق نتيجة، أوقف التنزيلات ومكالمات الفيديو على هذا الجهاز وعلى الأجهزة الأخرى في الشبكة نفسها. وتعتمد نتائج Wi-Fi أيضًا على قربك من الراوتر.","unit.mbps":"Mbps","unit.ms":"ms","unit.mbps_down":"Mbps تنزيل","unit.mbps_up":"Mbps رفع","res.download":"التنزيل","res.upload":"الرفع","res.ping":"زمن الاستجابة","res.jitter":"الاهتزاز","res.label":"نتائج اختبار السرعة","res.loaded":"زمن الاستجابة تحت الحمل","loaded.good":"ممتاز: يبقى اتصالك سريع الاستجابة أثناء الانشغال.","loaded.fair":"مقبول: قد تتقطع المكالمات والألعاب أثناء التنزيل.","loaded.bad":"مرتفع (bufferbloat): يتأخر الاتصال كثيراً عند الانشغال. قد يساعد راوتر بإدارة طوابير ذكية (SQM).","clk.now":"الوقت الآن","clk.elapsed":"وقت الاختبار","off.title":"لا يوجد اتصال بالإنترنت","off.text":"تعذّر الوصول إلى الشبكة. يرجى التحقق من اتصالك والمحاولة لاحقًا.","off.retry":"حاول مرة أخرى","conn.lead":"ما يمكن للإنترنت أن يراه عن اتصالك الآن. تأتي التفاصيل من متصفحك ومن خدمات بحث عامة، لذا اعتبر الموقع تقريبياً.","conn.isp":"مزود الإنترنت","conn.ip":"عنوان IP","conn.ipv4":"عنوان IPv4","conn.ipv6":"عنوان IPv6","conn.mac":"عنوان MAC","conn.location":"الموقع","conn.testServer":"خادم الاختبار","conn.networkType":"نوع الشبكة","conn.detecting":"جارٍ الاكتشاف…","conn.unavailable":"غير متاح","conn.noipv6":"لم يتم اكتشافه (لا يوجد IPv6 على هذا الاتصال)","conn.mac_na":"غير متاح: لا تسمح المتصفحات للمواقع بقراءة عنوان MAC.","conn.net.unknown":"لم يذكره هذا المتصفح","conn.net.wifi":"واي فاي","conn.net.cellular":"بيانات الجوال","conn.net.ethernet":"إيثرنت (كابل)","conn.net.bluetooth":"بلوتوث","conn.net.other":"أخرى","conn.refresh":"تحديث التفاصيل","conn.note":"يتم البحث في متصفحك من خادمنا وipify وipwho.is. لا يُخزَّن أي شيء على خوادمنا.","svc.lead":"الحالة المباشرة للتطبيقات وشبكات الجوال الشائعة. نستخدم صفحة الحالة حيث تنشرها الخدمة، ونتحقق في الباقي من إمكانية الوصول إلى الموقع من اتصالك.","svc.group.apps":"التطبيقات والمواقع","svc.group.telecom":"شبكات الجوال والنطاق العريض","svc.operational":"تعمل","svc.degraded":"أداء متراجع","svc.outage":"انقطاع","svc.unreachable":"تعذر الوصول","svc.checking":"جارٍ الفحص…","svc.all_ok":"كل ما فحصناه يعمل.","svc.issues":"توجد مشكلة في {n} خدمة.","svc.checked":"آخر فحص في {time}.","svc.refresh":"افحص مرة أخرى","svc.official":"صفحة الحالة الرسمية","svc.probe":"فحص إمكانية الوصول","svc.open":"فتح {name}","svc.note":"\"فحص إمكانية الوصول\" يعني أن هذا المتصفح استطاع أو لم يستطع فتح الموقع. ليست حالة رسمية، وقد يسبب مانع الإعلانات أو حظر الشبكة ظهور \"تعذر الوصول\".","act.share":"مشاركة النتيجة","act.save":"حفظ النتيجة","act.saved":"تم الحفظ","act.image":"تنزيل الصورة","act.copy":"نسخ النص","act.copied":"تم النسخ","share.title":"سرعة الإنترنت لدي","share.text":"سرعة الإنترنت لدي: {down} تنزيل، {up} رفع، وزمن استجابة {ping} ms. اختبر سرعتك مجانًا:","share.whatsapp":"WhatsApp","share.facebook":"Facebook","share.x":"X","share.telegram":"Telegram","share.menu":"المشاركة عبر","hist.title":"النتائج المحفوظة","hist.empty":"لا توجد نتائج محفوظة بعد. أجرِ اختبارًا ثم اضغط \"حفظ النتيجة\".","hist.note":"تُحفظ النتائج في هذا المتصفح فقط. لا يُرسل أي شيء إلى خادم.","hist.clear":"مسح الكل","hist.delete":"حذف","hist.item":"{down} تنزيل، {up} رفع، {ping} ms استجابة، {jitter} ms اهتزاز","info.h2.intro":"اختبار سرعة الإنترنت المجاني: افحص التنزيل والرفع وزمن الاستجابة","info.intro":"يُظهر لك اختبار سرعة الإنترنت المجاني هذا مدى سرعة اتصالك الفعلية خلال نحو 25 ثانية. اضغط \"ابدأ اختبار السرعة\" وسيقيس سرعة التنزيل وسرعة الرفع وزمن الاستجابة والاهتزاز مع خادم اختبار السرعة الخاص بنا. يعمل على أي هاتف أو جهاز لوحي أو حاسوب، عبر Wi-Fi أو بيانات الجوال أو الكابل، ولا يتطلب إنشاء حساب.","info.h2.mean":"ماذا تعني النتائج","info.mean.1":"سرعة التنزيل (Mbps): مدى سرعة وصول البيانات إليك. تتحكم في بث الفيديو وتحميل صفحات الويب وتحديث التطبيقات وتنزيل الملفات.","info.mean.2":"سرعة الرفع (Mbps): مدى سرعة إرسالك للبيانات. تهم في مكالمات الفيديو والنسخ الاحتياطي السحابي ومشاركة الملفات الكبيرة والبث المباشر.","info.mean.3":"زمن الاستجابة (ms): التأخير بين جهازك والخادم. الأقل أفضل، وأقل من 20 ms ممتاز للألعاب والمكالمات.","info.mean.4":"الاهتزاز (ms): مقدار تغيّر زمن الاستجابة. الأقل أفضل، والاهتزاز الثابت يعني مكالمات وألعابًا سلسة.","info.h2.good":"ما هي سرعة الإنترنت الجيدة؟","info.good":"كدليل تقريبي، تكفي سرعة من 5 إلى 10 Mbps لبث فيديو واحد بجودة HD، وتناسب سرعة 25 Mbps أسرة صغيرة، وتريح سرعة 100 Mbps أو أكثر عدة أشخاص يبثون ويعملون من المنزل ويلعبون في الوقت نفسه. تحتاج مكالمات الفيديو إلى سرعة رفع ثابتة تبلغ بضعة Mbps، لذا فإن التنزيل السريع وحده لا يضمن مكالمة جيدة.","info.h2.accurate":"كيف تحصل على أدق نتيجة لاختبار السرعة","info.acc.1":"أوقف التنزيلات والبث ومكالمات الفيديو على كل جهاز في شبكتك.","info.acc.2":"اقترب من الراوتر، أو صِل جهازًا به بكابل.","info.acc.3":"أغلق علامات تبويب المتصفح الأخرى وأوقف أي VPN.","info.acc.4":"كرر الاختبار مرتين أو ثلاث مرات وقارن النتائج.","info.h2.fix":"كيف تعالج بطء الإنترنت","info.fix.1":"أعد تشغيل الراوتر والمودم، ثم انتظر دقيقتين.","info.fix.2":"ضع الراوتر في مكان مفتوح ومركزي، بعيدًا عن الجدران والأجهزة.","info.fix.3":"انتقل إلى نطاق Wi-Fi بتردد 5 GHz للحصول على سرعة أعلى عن قرب.","info.fix.4":"افصل الأجهزة التي لا تستخدمها، وأوقف التحديثات الكبيرة في الخلفية.","info.fix.5":"حدّث البرنامج الثابت للراوتر، واستبدل الراوتر إذا كان عمره عدة سنوات.","info.fix.6":"إذا بقيت السرعة أقل بكثير من باقتك على اتصال الكابل، فتواصل مع مزوّد الإنترنت.","info.h2.faq":"الأسئلة الشائعة","faq.1.q":"ما مدى دقة اختبار سرعة الإنترنت هذا؟","faq.1.a":"يقيس مع خادم اختبار السرعة الخاص بنا، فيُظهر سرعتك الفعلية نحو هذا الخادم عبر الإنترنت العام. قد تختلف النتائج قليلًا بين مرة وأخرى لأن اتصالك وإشارة Wi-Fi والأجهزة الأخرى في شبكتك تتغير من لحظة إلى أخرى. أعد الاختبار مرتين أو ثلاث وقارن.","faq.2.q":"ما هي سرعة الإنترنت الجيدة؟","faq.2.a":"في معظم المنازل، تكفي سرعة تنزيل من 25 إلى 100 Mbps للبث بجودة HD ومكالمات الفيديو والتصفح. وتستفيد المنازل التي فيها أجهزة كثيرة أو بث 4K أو تنزيلات كبيرة من 100 إلى 500 Mbps. وتهم سرعة الرفع في مكالمات الفيديو والنسخ الاحتياطي السحابي والبث المباشر، لذا استهدف 10 Mbps على الأقل.","faq.3.q":"لماذا سرعتي أقل مما يعلنه مزوّد الخدمة؟","faq.3.a":"يعلن المزوّدون عن أفضل سرعة ممكنة على اتصال سلكي. يمكن لبُعد Wi-Fi والجدران وعمر الراوتر وساعات الذروة المسائية والأجهزة الأخرى والشبكة المزدحمة أن تقلل ما تحصل عليه فعلًا. الاختبار بكابل موصول بالراوتر يُظهر السرعة الحقيقية لباقتك.","faq.4.q":"ما الفرق بين سرعة التنزيل وسرعة الرفع؟","faq.4.a":"سرعة التنزيل هي مدى سرعة وصول البيانات إلى جهازك، وتؤثر في البث والتصفح وتنزيل الملفات. وسرعة الرفع هي مدى سرعة خروج البيانات من جهازك، وتؤثر في مكالمات الفيديو وإرسال الملفات الكبيرة ونشر الفيديوهات.","faq.5.q":"ما هو زمن الاستجابة (Ping) وما القيمة الجيدة له؟","faq.5.a":"زمن الاستجابة، ويسمى أيضًا التأخر، هو الوقت بالميلي ثانية الذي تستغرقه البيانات للوصول إلى الخادم والعودة. أقل من 20 ms ممتاز، ومن 20 إلى 50 ms جيد للألعاب والمكالمات، وأكثر من 100 ms قد يبدو بطيئًا.","faq.6.q":"ما هو الاهتزاز (Jitter)؟","faq.6.a":"الاهتزاز هو مقدار تغيّر زمن الاستجابة من لحظة إلى التالية. الاهتزاز المنخفض يعني اتصالًا مستقرًا. أما الاهتزاز المرتفع فيسبب تقطع مكالمات الفيديو وانقطاع الصوت وتأخر الألعاب حتى لو كانت سرعة التنزيل عالية.","faq.7.q":"هل اختبار السرعة هذا مجاني؟","faq.7.a":"نعم. إنه مجاني تمامًا، ولا يتطلب تسجيلًا، ويعمل على الهواتف والأجهزة اللوحية والحواسيب في أي متصفح حديث.","faq.8.q":"هل يستهلك الاختبار الكثير من البيانات؟","faq.8.a":"يقوم الاختبار الكامل بتنزيل ورفع بيانات اختبارية لمدة 25 ثانية تقريبًا، لذا قد يستهلك قدرًا ملحوظًا من البيانات على اتصال سريع. إذا كانت باقة الجوال لديك محدودة، فأجرِه عبر Wi-Fi أو نادرًا.","seo.home.title":"اختبار سرعة الإنترنت: افحص التنزيل والرفع وزمن الاستجابة (مجاني)","seo.home.desc":"اختبار سرعة إنترنت مجاني. افحص سرعة التنزيل وسرعة الرفع وزمن الاستجابة والاهتزاز خلال 25 ثانية. يعمل على الهاتف والكمبيوتر دون تسجيل. تعرّف على السرعة الجيدة.","unit.gbps":"Gbps","unit.gbps_down":"Gbps تنزيل","unit.gbps_up":"Gbps رفع"}'),
        ('youtube', N'{"yt.key.h":"YouTube API key","yt.key.lead":"No YouTube API key is saved yet. Enter it once (it is checked with YouTube and stored in the database) and it is never asked again. You can skip this and keep using the player without a key.","yt.key.label":"YouTube Data API v3 key","yt.key.master":"Master key","yt.key.save":"Save key","yt.key.saving":"Checking...","yt.key.skip":"Skip for now","yt.key.missing":"Enter the API key and the master key.","yt.h1":"YouTube music player","yt.placeholder.link":"Paste a YouTube link","yt.play":"Play","yt.needlink":"Paste a YouTube video link.","yt.lead":"Paste a YouTube link and play it here with YouTube''s own player. Add songs to a queue, shuffle and repeat.","yt.label":"YouTube link","yt.placeholder":"Song name or YouTube link","yt.go":"Search","yt.searching":"Searching…","yt.results":"Search results","yt.queue":"Queue","yt.add":"Add to queue","yt.remove":"Remove from queue","yt.quality":"Video quality","yt.quality.auto":"Quality: Auto","yt.fullscreen":"Fullscreen","yt.tip.desktop":"Tip: to keep music playing with the screen off, open your browser menu and turn on \"Desktop site\".","yt.tip.ok":"Got it","yt.serverdown":"Could not reach the music server. Please try again in a moment.","yt.pl.title":"My playlists","yt.pl.new":"New playlist name","yt.pl.create":"Create playlist","yt.pl.name":"Playlist name","yt.pl.saveq":"Save queue as playlist","yt.pl.addto":"Add songs to:","yt.pl.add":"Add to playlist","yt.pl.rename":"Rename playlist","yt.pl.play":"Play","yt.pl.delete":"Delete","yt.pl.up":"Move up","yt.pl.down":"Move down","yt.pl.nosongs":"No songs yet. Use the playlist button on a song to add it.","yt.pl.empty":"No playlists yet. Create one above.","yt.pl.pick":"Create a playlist first, then add songs to it.","yt.bg.on":"Background play is on: audio plays from your server, so it keeps going with the screen off.","yt.download":"Download MP3 (320 kbps)","yt.empty":"Nothing playing yet.","yt.empty2":"Paste a YouTube video link above.","yt.noresults":"No songs found.","yt.badlink":"This is not a YouTube video or playlist link.","yt.failed":"Could not reach YouTube. Please try again.","yt.video.on":"Video: On (tap for audio only)","yt.video.off":"Video: Off, audio only (tap to show)","yt.note":"Played with the official YouTube player, so YouTube ads and terms apply. The video must stay visible, and on phones it usually pauses when the screen turns off.","seo.yt.title":"YouTube Music Player: Queue, Shuffle and Repeat","seo.yt.desc":"Paste a YouTube link and play it with the official YouTube player, with queue, shuffle, repeat and lock-screen controls."}', N'{"yt.key.h":"YouTube API कुंजी","yt.key.lead":"अभी कोई YouTube API कुंजी सहेजी नहीं गई है। इसे एक बार दर्ज करें (YouTube से जाँचकर डेटाबेस में सहेजी जाती है), फिर दोबारा नहीं पूछी जाएगी। आप इसे छोड़कर बिना कुंजी के भी प्लेयर चला सकते हैं।","yt.key.label":"YouTube Data API v3 कुंजी","yt.key.master":"मास्टर कुंजी","yt.key.save":"कुंजी सहेजें","yt.key.saving":"जाँच हो रही है...","yt.key.skip":"अभी छोड़ें","yt.key.missing":"API कुंजी और मास्टर कुंजी दर्ज करें।","yt.h1":"यूट्यूब म्यूज़िक प्लेयर","yt.placeholder.link":"YouTube लिंक पेस्ट करें","yt.play":"चलाएं","yt.needlink":"YouTube वीडियो का लिंक पेस्ट करें।","yt.lead":"YouTube लिंक पेस्ट करें और YouTube के अपने प्लेयर से यहीं चलाएं। गाने कतार में जोड़ें, शफ़ल और रिपीट करें।","yt.label":"YouTube लिंक","yt.placeholder":"गाने का नाम या यूट्यूब लिंक","yt.go":"चलाएं","yt.searching":"खोज रहे हैं…","yt.results":"खोज के नतीजे","yt.queue":"कतार","yt.add":"कतार में जोड़ें","yt.remove":"कतार से हटाएं","yt.quality":"वीडियो क्वालिटी","yt.quality.auto":"क्वालिटी: ऑटो","yt.fullscreen":"फ़ुलस्क्रीन","yt.tip.desktop":"सुझाव: स्क्रीन बंद होने पर भी संगीत चलता रहे, इसके लिए ब्राउज़र मेन्यू खोलकर \"Desktop site\" चालू करें।","yt.tip.ok":"ठीक है","yt.serverdown":"म्यूज़िक सर्वर तक नहीं पहुँच सके। कृपया थोड़ी देर बाद फिर कोशिश करें।","yt.pl.title":"मेरी प्लेलिस्ट","yt.pl.new":"नई प्लेलिस्ट का नाम","yt.pl.create":"प्लेलिस्ट बनाएँ","yt.pl.name":"प्लेलिस्ट का नाम","yt.pl.saveq":"कतार को प्लेलिस्ट के रूप में सहेजें","yt.pl.addto":"गाने यहाँ जोड़ें:","yt.pl.add":"प्लेलिस्ट में जोड़ें","yt.pl.rename":"प्लेलिस्ट का नाम बदलें","yt.pl.play":"चलाएँ","yt.pl.delete":"हटाएँ","yt.pl.up":"ऊपर ले जाएँ","yt.pl.down":"नीचे ले जाएँ","yt.pl.nosongs":"अभी कोई गाना नहीं। जोड़ने के लिए गाने पर प्लेलिस्ट बटन दबाएँ।","yt.pl.empty":"अभी कोई प्लेलिस्ट नहीं। ऊपर से बनाएँ।","yt.pl.pick":"पहले एक प्लेलिस्ट बनाएँ, फिर उसमें गाने जोड़ें।","yt.bg.on":"बैकग्राउंड प्ले चालू है: ऑडियो आपके सर्वर से चल रहा है, इसलिए स्क्रीन बंद होने पर भी चलता रहेगा।","yt.download":"MP3 डाउनलोड करें (320 kbps)","yt.empty":"अभी कुछ नहीं चल रहा।","yt.empty2":"ऊपर YouTube वीडियो का लिंक पेस्ट करें।","yt.noresults":"कोई गाना नहीं मिला।","yt.badlink":"यह यूट्यूब वीडियो या प्लेलिस्ट का लिंक नहीं है।","yt.failed":"यूट्यूब तक नहीं पहुंच सके। कृपया फिर कोशिश करें।","yt.video.on":"वीडियो: चालू (सिर्फ़ ऑडियो के लिए दबाएँ)","yt.video.off":"वीडियो: बंद, सिर्फ़ ऑडियो (दिखाने के लिए दबाएँ)","yt.note":"आधिकारिक YouTube प्लेयर से चलता है, इसलिए YouTube के विज्ञापन और शर्तें लागू होती हैं। वीडियो दिखता रहना चाहिए, और फ़ोन में स्क्रीन बंद होने पर यह आम तौर पर रुक जाता है।","seo.yt.title":"YouTube म्यूज़िक प्लेयर: कतार, शफ़ल और रिपीट","seo.yt.desc":"YouTube लिंक पेस्ट करें और आधिकारिक YouTube प्लेयर से चलाएं, कतार, शफ़ल, रिपीट और लॉक-स्क्रीन कंट्रोल के साथ।"}', N'{"yt.key.h":"مفتاح YouTube API","yt.key.lead":"لم يتم حفظ مفتاح YouTube API بعد. أدخله مرة واحدة (يُتحقق منه لدى YouTube ويُخزَّن في قاعدة البيانات) ولن يُطلب مجددًا. يمكنك التخطي ومتابعة استخدام المشغل بدون مفتاح.","yt.key.label":"مفتاح YouTube Data API v3","yt.key.master":"المفتاح الرئيسي","yt.key.save":"حفظ المفتاح","yt.key.saving":"جارٍ التحقق...","yt.key.skip":"تخطَّ الآن","yt.key.missing":"أدخل مفتاح API والمفتاح الرئيسي.","yt.h1":"مشغل موسيقى يوتيوب","yt.placeholder.link":"الصق رابط YouTube","yt.play":"تشغيل","yt.needlink":"الصق رابط فيديو YouTube.","yt.lead":"ال