        ('creta', N'{"dance.label":"Dancing doodle","dance.auto":"Auto","dance.stick":"Stickman","dance.trio":"Trio","dance.robot":"Robot","dance.cat":"Cat","dance.blob":"Blob","dance.lines":"Lines","creta.h1":"Creta audio player","creta.lead":"Play the tracks, right in your browser.","creta.empty":"No tracks yet.","creta.empty2":"Copy audio files into the public/audio folder and build the site. The playlist is created from them.","creta.now":"Now playing","creta.playlist":"Playlist","creta.play":"Search","creta.pause":"Pause","creta.prev":"Previous track","creta.next":"Next track","creta.shuffle":"Shuffle","creta.repeat":"Repeat","creta.volume":"Volume","creta.seek":"Seek","creta.mute":"Mute","creta.untitled":"Untitled track","creta.error":"This track could not be loaded.","creta.edit.add":"Add songs","creta.edit.delete":"Delete song","creta.edit.uploading":"Uploading {name}…","creta.edit.uploaded":"Uploaded. The new songs are in the playlist.","creta.edit.removed":"Deleted.","creta.edit.confirm":"Delete \"{name}\" from the playlist?","creta.edit.badType":"{name} is not a supported audio file.","creta.edit.none":"The playlist is empty. Use + to add songs.","creta.edit.password":"Password","creta.edit.wrongPassword":"Wrong password. Nothing was changed.","creta.edit.cancel":"Cancel","creta.edit.addHelp":"Enter the password, choose the songs and upload them.","creta.edit.pick":"Choose songs","creta.edit.upload":"Upload","creta.edit.noFiles":"Choose at least one song.","creta.edit.failed":"The music server could not do this. Please try again.","seo.creta.title":"Creta Audio Player: Play Music Online","seo.creta.desc":"Creta is a simple online audio player with a playlist, seek bar, volume, shuffle and repeat. Works on phone and desktop.","creta.add.h1":"Add songs","creta.add.lead":"Upload audio files to the {name} player. They are saved on the server and added to the playlist.","creta.add.back":"Back to the player","creta.add.current":"Songs in this player"}', N'{"dan